    System.out.println("results = " + results);


    List<Long> productIds = results.stream()
            .map(tuple -> tuple.get(product.id))
            .distinct()
            .toList();







    List<UserSearchResponseDto> content = results.stream()
            .map(tuple -> UserSearchResponseDto.builder()
